import{readFileSync,writeFileSync}from'node:fs';
const p=process.env.AUDIT_PATH,r=JSON.parse(readFileSync(p,'utf8')),g=JSON.parse(readFileSync('data/gallery.json','utf8'));r.galleryCountAfter=g.count;r.galleryDelta=g.count-r.galleryCountBefore;r.galleryDeltaMatchesSuccessAdded=r.galleryDelta===r.successAdded;if(!r.galleryDeltaMatchesSuccessAdded)throw Error(`gallery.json 增量不一致：delta=${r.galleryDelta}, added=${r.successAdded}`);const paths=new Set(g.images.map(x=>x.path)),missing=r.addedPaths.filter(x=>!paths.has(x));if(missing.length)throw Error(`gallery.json 缺少新增记录：${missing.join(', ')}`);r.sampleChecks=r.addedPaths.length?[r.addedPaths[0],r.addedPaths.at(-1)].filter((x,i,a)=>a.indexOf(x)===i):[];r.completedAt=new Date().toISOString();writeFileSync(p,JSON.stringify(r,null,2)+'\n');console.log(`图库数量：${r.galleryCountBefore} -> ${r.galleryCountAfter}`);
